/** dedupe + sequence */
function accept(state, cid, msg) {
  // Write your solution here
  const seq = Object.keys(state.byKey).length + 1;
  return { status: 201, seq, state: { lastSeq: { ...state.lastSeq, [cid]: seq }, byKey: { ...state.byKey, [msg.clientMessageId]: seq } } };
}

